'use client';

import { useState, useEffect } from 'react';
import styles from './realistic-button.module.css';
import { useSound } from '@/hooks/use-sound';

type TextState = 'off' | 'drawing' | 'on';

export default function RealisticButton() {
    const [isActive, setIsActive] = useState(false);
    const [isPressed, setIsPressed] = useState(false);
    const [textState, setTextState] = useState<TextState>('off');

    const playClick = useSound("/audio/ui-sounds/mech-key-press.mp3");

    useEffect(() => {
        if (isActive) {
            setTextState('drawing');
            const timer = setTimeout(() => setTextState('on'), 900);
            return () => clearTimeout(timer);
        } else {
            setTextState('off');
        }
    }, [isActive]);

    const onClick = () => {
        playClick();
        setIsPressed(true);
        setIsActive(false);
        setTimeout(() => setIsPressed(false), 200);
    }

    return (
        <div className={`${styles.wrap} sm:scale-[0.6] scale-[0.5]`}>
            <button
                className={`${styles.button} ${isPressed ? styles.buttonPressed : ''} relative overflow-hidden w-[250px] h-[96px] bg-black z-20 border-transparent rounded-[24px]`}
                onMouseEnter={() => setIsActive(true)}
                onClick={onClick}
                onMouseLeave={() => { setIsActive(false); setIsPressed(false); }}
                onMouseDown={() => setIsPressed(true)}
                onMouseUp={() => setIsPressed(false)}
                onTouchStart={() => setIsPressed(true)}
                onTouchEnd={() => setIsPressed(false)}
                style={{
                    boxShadow: isActive || isPressed
                        ? 'inset 0 1px 1px rgba(255, 255, 255, 0.6), inset 0 -6px 1px -4px #ff7300, inset 0 -15px 6px -8px #cc5500,'
                        : 'inset 0 1px 1px rgb(255 255 255 / 40%), inset 0 -6px 1px -4px #ff7300, inset 0 -15px 6px -8px #ff6600',
                    transform: isPressed ? 'scale(0.94)' : 'scale(1)',
                    transition: isPressed
                        ? 'transform 0.07s ease, box-shadow 0.07s ease'
                        : 'transform 0.2s ease, box-shadow 0.3s ease',
                }}
            >
                <div className={`${styles.corner} absolute opacity-10 transition-all duration-400`}></div>

                <div
                    className={`${styles.inner} z-10 absolute flex items-center justify-center rounded-[20px] transition-all duration-300`}
                    style={{
                        inset: '14px 13px',
                        background: 'linear-gradient(180deg, #232324 5%, #46484b 100%)',
                        boxShadow: 'inset 0 -5px 15px -1px rgba(0, 0, 0, 0.3), inset 0 -4px 3px -3px black, inset 0 -10px 20px -8px rgb(255 255 255 / 40%), inset 0 1px 0 1px rgb(255 255 255 / 20%)'
                    }}
                >
                    <svg
                        width="100%"
                        height="100%"
                        viewBox="0 0 184 68"
                        xmlns="http://www.w3.org/2000/svg"
                        style={{ overflow: 'visible' }}
                    >
                        {/* {showGlow && (
                            <text
                                x="92"
                                y="34"
                                dominantBaseline="middle"
                                textAnchor="middle"
                                className={glowClass}
                            >
                                Start For Free
                            </text>
                        )} */}
                        <text
                            x="92"
                            y="34"
                            dominantBaseline="middle"
                            textAnchor="middle"
                            className={isPressed ? styles.svgTextBlink : ''}
                            style={{ fontSize: '26px', fill: isPressed ? 'rgb(147 147 147)' : 'rgb(247 245 243 / 70%)' }}
                        >
                            Start For Free
                        </text>
                    </svg>
                </div>
            </button>

            <div
                className={`${styles.led} absolute z-30 rounded-full w-1.5 h-1.5`}
                style={{
                    top: '100%',
                    marginTop: '14px',
                    backgroundColor: '#f35f3a',
                    boxShadow: '0 -10px 35px 17px #ff5100, inset 0 1px 2px 0px rgba(255, 255, 255, 0.6), 0 0 0px 3px rgb(0 0 0 / 60%), 0 0 2px 4px rgba(152, 81, 0, 0.8)',
                }}
            ></div>

            <div
                className={`${styles.bg} absolute z-10 bg-black rounded-[30px] overflow-hidden`}
                style={{
                    inset: '-5px',
                    boxShadow: isPressed
                        ? '0 20px 10px -10px rgba(0, 0, 0, 0.3), inset 4px 0 18px 6px rgba(0, 0, 0, 0.95), inset -4px 0 18px 6px rgba(0, 0, 0, 0.95), inset 0 4px 18px 6px rgba(0, 0, 0, 0.95), inset 0 -4px 18px 6px rgba(0, 0, 0, 0.95)'
                        : isActive
                            ? '0 20px 10px -10px rgba(0, 0, 0, 0.3), inset 0 0 28px 10px rgba(255, 100, 0, 0.45)'
                            : '0 20px 10px -10px rgba(0, 0, 0, 0.3)',
                    transition: isPressed ? 'box-shadow 0.07s ease' : 'box-shadow 0.25s ease',
                }}
            >
                <div
                    className="absolute inset-0 rounded-[30px] z-10 pointer-events-none"
                    style={{
                        boxShadow:
                            'inset 0 -2px 0px -1px rgb(120 176 255 / 32%), inset 0 0 5px 1px black, inset 0 0 0 1px black',
                    }}
                ></div>
                <div
                    className={`${styles.shine1} absolute`}
                    style={{
                        width: '10px',
                        height: '10px',
                        left: '50%',
                        bottom: '0',
                        transform: 'translateX(-50%)',
                        margin: 'auto',
                        borderRadius: '50%',
                        filter: 'blur(2px)',
                        backgroundColor: 'rgb(255, 115, 0)',
                    }}
                ></div>
                <div className={`${styles.shine2} absolute transition-all duration-500 opacity-0`}></div>
            </div>

            <div className={`${styles.bgGlow} absolute z-0 transition-all duration-500`}></div>
        </div>
    );
}

.wrap {
    --radius: 24px;
    --bg: #000000;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-direction: column;
    position: relative;
    pointer-events: none;
    width: fit-content;
}

.wrap::before {
    content: "";
    position: absolute;
    width: 250%;
    height: 250%;
    border-radius: var(--radius);
    background-color: rgba(255, 255, 255, 0.05);
    filter: blur(60px);
    transform: skewY(-20deg);
}

.wrap::after {
    content: "";
    position: absolute;
    width: 100%;
    height: 100%;
    border-radius: var(--radius);
    background-color: rgba(0, 0, 0, 0.5);
    filter: blur(30px);
}

.button {
    box-shadow: inset 0 1px 1px rgb(255 255 255 / 40%),
        inset 0 -6px 1px -4px #ff7300,
        inset 0 -15px 6px -8px #ff6600;
    cursor: pointer;
    pointer-events: auto;
}

.button::before {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: calc(var(--radius) * 0.8);
    border-top: 40px solid #414244;
    border-left: 32px solid #2b2b2c;
    border-right: 32px solid #2b2b2c;
    border-bottom: 40px solid #15161a;
    filter: blur(5px);
    transition: all 0.5s ease;
}

.button::after {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    margin: auto;
    top: 101%;
    height: 40px;
    width: 96px;
    border-radius: 40px 40px 0 0;
    background: #ff7300;
    filter: contrast(10) blur(7px);
    transition: all 0.3s ease;
    opacity: 1;
}

.buttonActive::after {
    width: 120px;
    background: #ff9500;
    filter: contrast(12) blur(9px);
}

.buttonPressed::before {
    border-top: 16px solid #414244;
    border-left: 18px solid #2b2b2c;
    border-right: 18px solid #2b2b2c;
    border-bottom: 16px solid #15161a;
    transition: all 0.07s ease;
}

/* --- corners --- */

.corner {
    transition: all 0.4s ease;
    opacity: 0.1;
}

.corner::before,
.corner::after {
    content: "";
    position: absolute;
    top: 0;
    border-top: 44px solid white;
    border-left: 12px solid transparent;
    border-right: 12px solid transparent;
    filter: blur(5px);
    transition: all 0.4s ease;
}

.corner::before {
    left: 8px;
    transform: rotate(-40deg);
}

.corner::after {
    right: 8px;
    transform: rotate(40deg);
}

.cornerActive {
    opacity: 0.65;
}

.cornerActive::before,
.cornerActive::after {
    border-top-color: #ff8c00;
    filter: blur(5px);
}

/* --- inner panel --- */

.inner {
    transition: all 0.3s ease;
}

/* --- svg text states --- */

.svgTextOff {
    fill: #0a0a0a;
    stroke: none;
    font-size: 14px;
    font-weight: 600;
    letter-spacing: 1.5px;
    font-family: inherit;
}

.svgTextDrawing {
    fill: #0a0a0a;
    stroke: #ff9040;
    stroke-width: 0.6;
    stroke-dasharray: 1000;
    font-size: 14px;
    font-weight: 600;
    letter-spacing: 1.5px;
    font-family: inherit;
    animation: drawText 0.9s ease forwards;
}

.svgTextOn {
    fill: #ff9040;
    stroke: #ff9040;
    stroke-width: 0.3;
    stroke-dashoffset: 0;
    font-size: 14px;
    font-weight: 600;
    letter-spacing: 1.5px;
    font-family: inherit;
}

.svgTextGlowDrawing {
    fill: transparent;
    stroke: #ce7c02;
    stroke-width: 14;
    stroke-dasharray: 1000;
    font-size: 14px;
    font-weight: 600;
    letter-spacing: 1.5px;
    font-family: inherit;
    filter: blur(6px);
    opacity: 0.5;
    animation: drawText 0.9s ease forwards;
}

.svgTextGlowOn {
    fill: #ce7c02;
    stroke: none;
    font-size: 14px;
    font-weight: 600;
    letter-spacing: 1.5px;
    font-family: inherit;
    filter: blur(6px);
    opacity: 0.5;
}

@keyframes drawText {
    from {
        stroke-dashoffset: 1000;
    }

    to {
        stroke-dashoffset: 0;
    }
}

.svgTextBlink {
    animation: textBlink 0.5s step-end infinite;
}

@keyframes textBlink {

    0%,
    100% {
        opacity: 1;
    }

    100% {
        opacity: 0.4;
    }
}

/* --- symbol body --- */

.symbol {
    fill: #212123;
    transition: fill 0.4s ease;
}

.symbolActive {
    fill: #2a1808;
}

/* --- symbol stroke paths (idle: animated draw) --- */

.symbolPath {
    filter: brightness(1.1) contrast(1.1);
}

.symbolPath path {
    stroke-dasharray: 650;
    stroke-dashoffset: -650;
    stroke-width: 5;
    stroke: #ff7a3c;
    animation: symbolPath 2s ease-in-out;
}

.symbolPathGlow path {
    stroke-dasharray: 650;
    stroke-dashoffset: -650;
    stroke-width: 30;
    stroke: #ce7c02;
    filter: blur(30px);
    animation: symbolPath 2s ease-in-out;
}

.symbolPath circle {
    fill: #ff593c;
    opacity: 0;
    animation: symbolCircle 2s ease-in-out;
}

.symbolPathGlow circle {
    fill: #ce7c02;
    filter: blur(30px);
    opacity: 0;
    animation: symbolCircle 2s ease-in-out;
}

/* --- symbol stroke paths (active: persistent orange glow) --- */

.symbolPathActive path {
    stroke-dashoffset: 0;
    stroke: #ff9040;
    animation: symbolGlowPulse 1.5s ease-in-out infinite alternate;
    opacity: 1;
}

.symbolPathGlowActive path {
    stroke-dashoffset: 0;
    animation: symbolGlowPulse 1.5s ease-in-out infinite alternate;
    opacity: 0.75;
}

.symbolPathActive circle {
    opacity: 1;
    animation: symbolGlowPulse 1.5s ease-in-out infinite alternate;
}

.symbolPathGlowActive circle {
    opacity: 0.6;
    animation: symbolGlowPulse 1.5s ease-in-out infinite alternate;
}

/* --- background layers --- */

.bg {
    border-radius: calc(var(--radius) * 1.25);
}

.bg::before {
    content: "";
    position: absolute;
    border-radius: inherit;
    inset: 0;
    z-index: 1;
}

.shine1 {
    animation: bg 2.4s linear 0.3s infinite;
}

.shine2 {
    transition: all 0.5s linear;
}

.shine2::before {
    content: "";
    position: absolute;
    z-index: 0;
    transition: all 0.3s ease;
    background: rgb(255, 115, 0);
    width: 10px;
    height: 10px;
    left: 0;
    right: 0;
    bottom: 0;
    margin: auto;
    border-radius: 50%;
    filter: blur(2px);
    animation: bg 2.4s linear infinite;
}

.bgGlow {
    position: absolute;
    inset: 0;
    border-radius: calc(var(--radius) * 1.25);
    transition: all 0.5s linear;
}

.bgGlow::before {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background: linear-gradient(to bottom, #ff7300 0%, black 100%);
    filter: blur(12px);
    opacity: 0;
    animation: bgGlow 3s linear infinite;
}

.led {
    animation: none;
}

/* --- keyframes --- */

@keyframes symbolPath {
    0% {
        stroke-dashoffset: -650;
    }

    50% {
        stroke-dashoffset: 0;
    }

    100% {
        stroke-dashoffset: 650;
    }
}

@keyframes symbolCircle {
    0% {
        opacity: 0;
    }

    50% {
        opacity: 1;
    }

    100% {
        opacity: 0;
    }
}

@keyframes symbolGlowPulse {
    0% {
        opacity: 0.8;
    }

    100% {
        opacity: 1;
    }
}

@keyframes bg {
    0% {
        transform: translateY(0) scale(0);
    }

    12% {
        transform: translateY(0) scale(25);
    }

    60%,
    100% {
        transform: translateY(-280px) scale(20, 18);
    }
}

@keyframes bgGlow {
    0% {
        opacity: 0;
    }

    40% {
        opacity: 1;
    }

    80%,
    100% {
        opacity: 0;
    }
}

@keyframes bgGlowPulse {
    0% {
        opacity: 0.6;
        filter: blur(20px);
    }

    100% {
        opacity: 0.9;
        filter: blur(25px);
    }
}

@keyframes ledPulse {
    0% {
        box-shadow: 0 -5px 14px 4px #ff7300,
            inset 0 1px 2px 0px rgba(255, 255, 255, 0.6),
            0 0 0px 2px rgba(255, 130, 0, 0.25);
    }

    100% {
        box-shadow: 0 -6px 18px 6px #ff9500,
            inset 0 1px 2px 0px rgba(255, 255, 255, 0.8),
            0 0 0px 2px rgba(255, 160, 0, 0.35);
    }
}

@keyframes reflexLedTurnOff {

    30%,
    60% {
        box-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.4),
            inset 0 -6px 1px -4px #9b8100,
            inset 0 -15px 6px -8px #373326;
    }

    60.1%,
    65% {
        box-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.4),
            inset 0 -6px 1px -4px rgba(255, 255, 255, 0.1),
            inset 0 -15px 6px -8px rgba(255, 255, 255, 0.1);
    }

    65.1%,
    70% {
        box-shadow: inset 0 1px 1px rgb(255 255 255 / 40%),
            inset 0 -6px 1px -4px #9b8100,
            inset 0 -15px 6px -8px #373326;
    }

    70.1%,
    100% {
        box-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.4),
            inset 0 -6px 1px -4px rgba(255, 255, 255, 0.1),
            inset 0 -15px 6px -8px rgba(255, 255, 255, 0.1);
    }
}

@keyframes reflexLedBlurTurnOff {

    30%,
    60% {
        background: #ffc400;
    }

    60.1%,
    65% {
        background: transparent;
    }

    65.1%,
    70% {
        background: #ffc400;
    }

    70.1%,
    100% {
        background: transparent;
    }
}

@keyframes bgBeforeTurnOff {

    30%,
    60% {
        box-shadow: inset 0 -2px 0px -1px rgba(255, 230, 120, 0.3),
            inset 0 0 5px 1px black,
            inset 0 0 0 1px black;
    }

    60.1%,
    65% {
        box-shadow: inset 0 -2px 0px -1px rgba(160, 160, 160, 0.3),
            inset 0 0 5px 1px black,
            inset 0 0 0 1px black;
    }

    65.1%,
    70% {
        box-shadow: inset 0 -2px 0px -1px rgba(255, 230, 120, 0.3),
            inset 0 0 5px 1px black,
            inset 0 0 0 1px black;
    }

    70.1%,
    100% {
        box-shadow: inset 0 -2px 0px -1px rgba(160, 160, 160, 0.3),
            inset 0 0 5px 1px black,
            inset 0 0 0 1px black;
    }
}

import { useCallback, useEffect, useRef } from "react";

/**
 * Custom React hook to load and play a sound from a given URL using the Web Audio API.
 *
 * This hook fetches the audio file at the specified URL, decodes it, and prepares it for playback.
 * It returns a `play` function that can be called to play the loaded sound.
 *
 * @param url - The URL of the audio file to load and play.
 * @returns A function that, when called, plays the loaded sound.
 *
 * @remarks
 * - If the Web Audio API is not supported in the browser, a warning is logged and playback is disabled.
 * - The audio context and buffer are managed internally using React refs.
 * - Errors during fetching or decoding the audio are logged to the console.
 *
 * @example
 * ```tsx
 * const playClick = useSound('/sounds/click.mp3');
 * // Later in an event handler:
 * playClick();
 * ```
 */
export function useSound(url: string) {
  const audioCtxRef = useRef<AudioContext | null>(null);
  const bufferRef = useRef<AudioBuffer | null>(null);

  useEffect(() => {
    const AudioContextClass =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext: typeof AudioContext })
        .webkitAudioContext;

    if (!AudioContextClass) {
      console.warn("Web Audio API is not supported in this browser.");
      return;
    }

    const audioCtx = new AudioContextClass();
    audioCtxRef.current = audioCtx;

    fetch(url)
      .then((res) => res.arrayBuffer())
      .then((data) => audioCtx.decodeAudioData(data))
      .then((decoded) => {
        bufferRef.current = decoded;
      })
      .catch((err) => {
        console.log(`Failed to load click sound from ${url}:`, err);
      });
  }, [url]);

  const play = useCallback((volume: number = 1) => {
    if (audioCtxRef.current && bufferRef.current) {
      const source = audioCtxRef.current.createBufferSource();
      const gainNode = audioCtxRef.current.createGain();

      source.buffer = bufferRef.current;
      gainNode.gain.value = volume;

      source.connect(gainNode);
      gainNode.connect(audioCtxRef.current.destination);
      source.start(0);
    }
  }, []);

  return play;
}
